    4: { de: "American College of Sports Medicine (2009): Progression models in resistance training for healthy adults (Position Stand; ersetzt durch [F3], nur als älterer Stand genannt). <i>Med Sci Sports Exerc</i> 41(3):687–708. <a href=\"https://doi.org/10.1249/MSS.0b013e3181915670\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1249/MSS.0b013e3181915670</a>", en: "American College of Sports Medicine (2009): Progression models in resistance training for healthy adults (Position Stand; superseded by [F3], mentioned only as an older statement). <i>Med Sci Sports Exerc</i> 41(3):687–708. <a href=\"https://doi.org/10.1249/MSS.0b013e3181915670\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1249/MSS.0b013e3181915670</a>" },
    5: { de: "Garber CE et al. (2011): Quantity and quality of exercise for developing and maintaining cardiorespiratory, musculoskeletal, and neuromotor fitness in apparently healthy adults (ACSM Position Stand). <i>Med Sci Sports Exerc</i> 43(7):1334–1359. <a href=\"https://doi.org/10.1249/MSS.0b013e318213fefb\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1249/MSS.0b013e318213fefb</a>", en: "Garber CE et al. (2011): Quantity and quality of exercise for developing and maintaining cardiorespiratory, musculoskeletal, and neuromotor fitness in apparently healthy adults (ACSM Position Stand). <i>Med Sci Sports Exerc</i> 43(7):1334–1359. <a href=\"https://doi.org/10.1249/MSS.0b013e318213fefb\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1249/MSS.0b013e318213fefb</a>" },
    6: { de: "Schoenfeld BJ, Ogborn D, Krieger JW (2017): Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. <i>J Sports Sci</i> 35(11):1073–1082. <a href=\"https://doi.org/10.1080/02640414.2016.1210197\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1080/02640414.2016.1210197</a>", en: "Schoenfeld BJ, Ogborn D, Krieger JW (2017): Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. <i>J Sports Sci</i> 35(11):1073–1082. <a href=\"https://doi.org/10.1080/02640414.2016.1210197\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1080/02640414.2016.1210197</a>" },
    7: { de: "Schoenfeld BJ et al. (2017): Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis. <i>J Strength Cond Res</i> 31(12):3508–3523. <a href=\"https://doi.org/10.1519/JSC.0000000000002200\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1519/JSC.0000000000002200</a>", en: "Schoenfeld BJ et al. (2017): Strength and hypertrophy adaptations between low- vs. high-load resistance training: a systematic review and meta-analysis. <i>J Strength Cond Res</i> 31(12):3508–3523. <a href=\"https://doi.org/10.1519/JSC.0000000000002200\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1519/JSC.0000000000002200</a>" },
    8: { de: "Schoenfeld BJ, Ogborn D, Krieger JW (2016): Effects of resistance training frequency on measures of muscle hypertrophy: a systematic review and meta-analysis. <i>Sports Med</i> 46:1689–1697. <a href=\"https://doi.org/10.1007/s40279-016-0543-8\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1007/s40279-016-0543-8</a>", en: "Schoenfeld BJ, Ogborn D, Krieger JW (2016): Effects of resistance training frequency on measures of muscle hypertrophy: a systematic review and meta-analysis. <i>Sports Med</i> 46:1689–1697. <a href=\"https://doi.org/10.1007/s40279-016-0543-8\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1007/s40279-016-0543-8</a>" },
    9: { de: "Schoenfeld BJ et al. (2016): Longer interset rest periods enhance muscle strength and hypertrophy in resistance-trained men. <i>J Strength Cond Res</i> 30(7):1805–1812. <a href=\"https://doi.org/10.1519/JSC.0000000000001272\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1519/JSC.0000000000001272</a>", en: "Schoenfeld BJ et al. (2016): Longer interset rest periods enhance muscle strength and hypertrophy in resistance-trained men. <i>J Strength Cond Res</i> 30(7):1805–1812. <a href=\"https://doi.org/10.1519/JSC.0000000000001272\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1519/JSC.0000000000001272</a>" },
    10: { de: "Grgic J et al. (2018): Effects of rest interval duration in resistance training on measures of muscular strength: a systematic review. <i>Sports Med</i> 48:137–151. <a href=\"https://doi.org/10.1007/s40279-017-0788-x\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1007/s40279-017-0788-x</a>", en: "Grgic J et al. (2018): Effects of rest interval duration in resistance training on measures of muscular strength: a systematic review. <i>Sports Med</i> 48:137–151. <a href=\"https://doi.org/10.1007/s40279-017-0788-x\" target=\"_blank\" rel=\"noopener noreferrer\" referrerpolicy=\"no-referrer\">doi:10.1007/s40279-017-0788-x</a>" },
